from AlgorithmImports import *
from collections import deque
from decimal import Decimal, ROUND_FLOOR


class IndependentSpyAaplStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol
        self.required_symbols = (self.spy, self.aapl, self.ibm, self.bac, self.aig)

        self.spy_closes = deque(maxlen=101)
        self.aapl_closes = deque(maxlen=4)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0
        self.strategy_a_portfolio_percentage = 1.0
        self.strategy_b_cash_amount = Decimal("20000")

    def OnData(self, data: Slice):
        self._apply_splits(data)

        if data.Bars.ContainsKey(self.spy):
            self.spy_closes.append(data.Bars[self.spy].Close)

        if data.Bars.ContainsKey(self.aapl):
            aapl_bar = data.Bars[self.aapl]
            self.aapl_closes.append(aapl_bar.Close)
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        if any(not data.Bars.ContainsKey(symbol) for symbol in self.required_symbols):
            return

        if len(self.spy_closes) < 101 or len(self.aapl_closes) < 4 or not self.aapl_rsi.IsReady:
            return

        spy_close = self.spy_closes[-1]
        spy_previous_close = self.spy_closes[-2]
        spy_sma = sum(list(self.spy_closes)[-100:]) / Decimal(100)
        spy_previous_sma = sum(list(self.spy_closes)[:100]) / Decimal(100)

        spy_crossed_below = (
            spy_previous_close >= spy_previous_sma and spy_close < spy_sma
        )
        spy_crossed_above = (
            spy_previous_close <= spy_previous_sma and spy_close > spy_sma
        )

        # Sells are evaluated before buys.
        if self.strategy_a_lot > 0 and spy_crossed_below:
            self.MarketOrder(self.spy, -self.strategy_a_lot)
            self.strategy_a_lot = 0

        if self.strategy_b_lot > 0 and self.aapl_rsi.Current.Value > Decimal(60):
            self.MarketOrder(self.aapl, -self.strategy_b_lot)
            self.strategy_b_lot = 0

        if self.strategy_a_lot == 0 and spy_crossed_above:
            quantity = self.CalculateOrderQuantity(
                self.spy, self.strategy_a_portfolio_percentage
            )
            if quantity > 0:
                self.MarketOrder(self.spy, quantity)
                self.strategy_a_lot = quantity

        if self.strategy_b_lot == 0:
            aapl_red_for_three_days = all(
                self.aapl_closes[index] < self.aapl_closes[index - 1]
                for index in range(1, 4)
            )
            available_cash = self.Portfolio.CashBook["USD"].Amount
            if aapl_red_for_three_days and available_cash >= self.strategy_b_cash_amount:
                aapl_close = self.aapl_closes[-1]
                quantity = int(
                    (self.strategy_b_cash_amount / aapl_close).to_integral_value(
                        rounding=ROUND_FLOOR
                    )
                )
                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity)
                    self.strategy_b_lot = quantity

    def _apply_splits(self, data: Slice):
        if data.Splits.ContainsKey(self.spy) and self.strategy_a_lot > 0:
            factor = data.Splits[self.spy].SplitFactor
            if factor > 0:
                self.strategy_a_lot = int(self.strategy_a_lot / factor)

        if data.Splits.ContainsKey(self.aapl) and self.strategy_b_lot > 0:
            factor = data.Splits[self.aapl].SplitFactor
            if factor > 0:
                self.strategy_b_lot = int(self.strategy_b_lot / factor)

