class IndependentDailyStrategiesAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = RollingWindow[float](102)
        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0
        self.strategy_a_order_pending = False
        self.strategy_b_order_pending = False

        # The percentage used by Strategy A is the whole portfolio (100%).
        self.strategy_a_portfolio_percentage = 1.0

    def OnData(self, data):
        bars = {}
        all_bars_present = True
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]
            else:
                all_bars_present = False

        if "SPY" in bars:
            self.spy_closes.Add(float(bars["SPY"].Close))

        if "AAPL" in bars:
            aapl_close = float(bars["AAPL"].Close)
            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_close
            self.aapl_rsi.Update(bars["AAPL"].EndTime, aapl_close)

        if not all_bars_present:
            return

        self.EvaluateStrategyA(float(bars["SPY"].Close))
        self.EvaluateStrategyB(float(bars["AAPL"].Close))

    def EvaluateStrategyA(self, spy_close):
        if self.spy_closes.Count < 101 or self.strategy_a_order_pending:
            return

        today_sma = sum(self.spy_closes[i] for i in range(100)) / 100.0
        yesterday_sma = sum(self.spy_closes[i] for i in range(1, 101)) / 100.0
        yesterday_close = self.spy_closes[1]
        crossed_above = yesterday_close <= yesterday_sma and spy_close > today_sma
        crossed_below = yesterday_close >= yesterday_sma and spy_close < today_sma

        if self.strategy_a_shares > 0:
            if crossed_below:
                self.strategy_a_order_pending = True
                self.MarketOrder(
                    self.symbols["SPY"],
                    -self.strategy_a_shares,
                    tag="Strategy A sell",
                )
            return

        if crossed_above:
            target_value = (
                self.strategy_a_portfolio_percentage
                * float(self.Portfolio.TotalPortfolioValue)
            )
            quantity = int(target_value // spy_close)
            if quantity > 0:
                self.strategy_a_order_pending = True
                self.MarketOrder(
                    self.symbols["SPY"], quantity, tag="Strategy A buy"
                )

    def EvaluateStrategyB(self, aapl_close):
        if not self.aapl_rsi.IsReady or self.strategy_b_order_pending:
            return

        if self.strategy_b_shares > 0:
            if float(self.aapl_rsi.Current.Value) > 60.0:
                self.strategy_b_order_pending = True
                self.MarketOrder(
                    self.symbols["AAPL"],
                    -self.strategy_b_shares,
                    tag="Strategy B sell",
                )
            return

        if self.aapl_red_streak >= 3 and float(self.Portfolio.Cash) >= 20_000.0:
            quantity = int(20_000.0 // aapl_close)
            if quantity > 0:
                self.strategy_b_order_pending = True
                self.MarketOrder(
                    self.symbols["AAPL"], quantity, tag="Strategy B buy"
                )

    def OnOrderEvent(self, order_event):
        if order_event.Status not in (OrderStatus.Filled, OrderStatus.PartiallyFilled):
            if order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                order = self.Transactions.GetOrderById(order_event.OrderId)
                if order.Tag.startswith("Strategy A"):
                    self.strategy_a_order_pending = False
                elif order.Tag.startswith("Strategy B"):
                    self.strategy_b_order_pending = False
            return

        order = self.Transactions.GetOrderById(order_event.OrderId)
        fill_quantity = int(order_event.FillQuantity)
        if order.Tag.startswith("Strategy A"):
            self.strategy_a_shares += fill_quantity
            if order_event.Status == OrderStatus.Filled:
                self.strategy_a_order_pending = False
        elif order.Tag.startswith("Strategy B"):
            self.strategy_b_shares += fill_quantity
            if order_event.Status == OrderStatus.Filled:
                self.strategy_b_order_pending = False

