class IndependentSlotsAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = deque(maxlen=101)
        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        # The percentage specified by Strategy A is the entire portfolio (100%).
        self.strategy_a_percent = 1.0
        self.strategy_a_lot = 0
        self.strategy_b_lot = 0
        self.strategy_a_pending = False
        self.strategy_b_pending = False

    def OnData(self, data: Slice):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        if data.Bars.ContainsKey(spy):
            self.spy_closes.append(float(data.Bars[spy].Close))

        if data.Bars.ContainsKey(aapl):
            aapl_bar = data.Bars[aapl]
            aapl_close = float(aapl_bar.Close)
            if self.aapl_previous_close is None:
                self.aapl_red_streak = 0
            elif aapl_close < self.aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_close
            self.aapl_rsi.Update(IndicatorDataPoint(aapl_bar.EndTime, aapl_bar.Close))

        # No strategy rule is evaluated unless every subscription supplied a bar.
        if any(not data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        spy_bar = data.Bars[spy]
        aapl_bar = data.Bars[aapl]

        # Every sell rule is evaluated before either strategy's buy rule.
        if self.strategy_a_lot > 0 and not self.strategy_a_pending and len(self.spy_closes) == 101:
            previous_sma = sum(list(self.spy_closes)[:100]) / 100.0
            current_sma = sum(list(self.spy_closes)[1:]) / 100.0
            previous_close = self.spy_closes[-2]
            current_close = self.spy_closes[-1]
            if previous_close >= previous_sma and current_close < current_sma:
                self.strategy_a_pending = True
                self.MarketOrder(spy, -self.strategy_a_lot, tag="Strategy A sell")

        if self.strategy_b_lot > 0 and not self.strategy_b_pending and self.aapl_rsi.IsReady:
            if self.aapl_rsi.Current.Value > 60:
                self.strategy_b_pending = True
                self.MarketOrder(aapl, -self.strategy_b_lot, tag="Strategy B sell")

        if self.strategy_a_lot == 0 and not self.strategy_a_pending and len(self.spy_closes) == 101:
            previous_sma = sum(list(self.spy_closes)[:100]) / 100.0
            current_sma = sum(list(self.spy_closes)[1:]) / 100.0
            previous_close = self.spy_closes[-2]
            current_close = self.spy_closes[-1]
            if previous_close <= previous_sma and current_close > current_sma:
                quantity = self.CalculateOrderQuantity(spy, self.strategy_a_percent)
                if quantity > 0:
                    self.strategy_a_pending = True
                    self.MarketOrder(spy, quantity, tag="Strategy A buy")

        if self.strategy_b_lot == 0 and not self.strategy_b_pending and self.aapl_rsi.IsReady:
            if self.aapl_red_streak >= 3 and self.Portfolio.Cash >= 20_000:
                quantity = floor(20_000 / float(aapl_bar.Close))
                if quantity > 0:
                    self.strategy_b_pending = True
                    self.MarketOrder(aapl, quantity, tag="Strategy B buy")

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status not in (OrderStatus.Filled, OrderStatus.PartiallyFilled):
            if order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                if order_event.Symbol == self.symbols["SPY"]:
                    self.strategy_a_pending = False
                elif order_event.Symbol == self.symbols["AAPL"]:
                    self.strategy_b_pending = False
            return

        if order_event.Symbol == self.symbols["SPY"]:
            self.strategy_a_lot = max(0, self.strategy_a_lot + int(order_event.FillQuantity))
            if order_event.Status == OrderStatus.Filled:
                self.strategy_a_pending = False
        elif order_event.Symbol == self.symbols["AAPL"]:
            self.strategy_b_lot = max(0, self.strategy_b_lot + int(order_event.FillQuantity))
            if order_event.Status == OrderStatus.Filled:
                self.strategy_b_pending = False

