class IndependentDailyStrategiesAlgorithm(QCAlgorithm):
    STRATEGY_A_PORTFOLIO_PERCENT = 1.0

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.add_equity(
                ticker, Resolution.DAILY
            ).symbol

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.WILDERS)

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

        # The extra bar permits a prior-day, fully formed SMA value for crossing.
        self.set_warm_up(101, Resolution.DAILY)

    def on_data(self, data: Slice):
        self._apply_splits(data)

        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        spy_bar = data.bars[spy] if data.bars.contains_key(spy) else None
        aapl_bar = data.bars[aapl] if data.bars.contains_key(aapl) else None

        previous_spy_close = self.previous_spy_close
        previous_spy_sma = self.previous_spy_sma

        if spy_bar is not None:
            self.spy_sma.update(spy_bar.end_time, spy_bar.close)
            self.previous_spy_close = spy_bar.close
            if self.spy_sma.is_ready:
                self.previous_spy_sma = self.spy_sma.current.value

        if aapl_bar is not None:
            if self.previous_aapl_close is None:
                self.aapl_red_streak = 0
            elif aapl_bar.close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self.previous_aapl_close = aapl_bar.close
            self.aapl_rsi.update(aapl_bar.end_time, aapl_bar.close)

        if self.is_warming_up:
            return

        # No strategy rule is evaluated unless all five daily bars are present.
        if any(not data.bars.contains_key(symbol) for symbol in self.symbols.values()):
            return

        spy_sma_today = self.spy_sma.current.value
        spy_crossed_below = (
            self.strategy_a_shares > 0
            and previous_spy_close is not None
            and previous_spy_sma is not None
            and previous_spy_close >= previous_spy_sma
            and spy_bar.close < spy_sma_today
        )

        # All sells are evaluated and submitted before either buy is evaluated.
        if spy_crossed_below:
            self.market_order(spy, -self.strategy_a_shares, tag="Strategy A sell")
            self.strategy_a_shares = 0

        if self.strategy_b_shares > 0 and self.aapl_rsi.current.value > 60:
            self.market_order(aapl, -self.strategy_b_shares, tag="Strategy B sell")
            self.strategy_b_shares = 0

        spy_crossed_above = (
            self.strategy_a_shares == 0
            and previous_spy_close is not None
            and previous_spy_sma is not None
            and previous_spy_close <= previous_spy_sma
            and spy_bar.close > spy_sma_today
        )
        if spy_crossed_above:
            quantity = self.calculate_order_quantity(
                spy, self.STRATEGY_A_PORTFOLIO_PERCENT
            )
            if quantity > 0:
                self.market_order(spy, quantity, tag="Strategy A buy")
                self.strategy_a_shares = quantity

        if self.strategy_b_shares == 0 and self.aapl_red_streak >= 3:
            cash_amount = 20_000
            if self.portfolio.cash >= cash_amount:
                quantity = int(cash_amount // aapl_bar.close)
                if quantity > 0:
                    self.market_order(aapl, quantity, tag="Strategy B buy")
                    self.strategy_b_shares = quantity

    def _apply_splits(self, data: Slice):
        for symbol, attribute in (
            (self.symbols["SPY"], "strategy_a_shares"),
            (self.symbols["AAPL"], "strategy_b_shares"),
        ):
            if not data.splits.contains_key(symbol):
                continue
            split = data.splits[symbol]
            if split.type != SplitType.SPLIT_OCCURRED or split.split_factor == 0:
                continue
            shares = getattr(self, attribute)
            if shares > 0:
                setattr(self, attribute, int(shares / split.split_factor))

