class IndependentDailyStrategiesAlgorithm(QCAlgorithm):
    SPY_ALLOCATION = 0.50
    AAPL_PURCHASE_DOLLARS = 20000

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_sma = self.SMA(self.symbols["SPY"], 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.symbols["AAPL"], 14, MovingAverageType.Wilders, Resolution.Daily
        )

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.spy_lot = 0
        self.aapl_lot = 0
        self.spy_order_pending = False
        self.aapl_order_pending = False

        self.SetWarmUp(100, Resolution.Daily)

    def OnData(self, data):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        spy_bar = data.Bars[spy] if data.Bars.ContainsKey(spy) else None
        aapl_bar = data.Bars[aapl] if data.Bars.ContainsKey(aapl) else None

        spy_crossed_above = False
        spy_crossed_below = False
        if spy_bar is not None and self.spy_sma.IsReady:
            current_spy_close = float(spy_bar.Close)
            current_spy_sma = float(self.spy_sma.Current.Value)
            if self.previous_spy_close is not None and self.previous_spy_sma is not None:
                spy_crossed_above = (
                    self.previous_spy_close <= self.previous_spy_sma
                    and current_spy_close > current_spy_sma
                )
                spy_crossed_below = (
                    self.previous_spy_close >= self.previous_spy_sma
                    and current_spy_close < current_spy_sma
                )
            self.previous_spy_close = current_spy_close
            self.previous_spy_sma = current_spy_sma

        if aapl_bar is not None:
            current_aapl_close = float(aapl_bar.Close)
            if self.previous_aapl_close is not None:
                if current_aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.previous_aapl_close = current_aapl_close

        if any(not data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return
        if self.IsWarmingUp or not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            return

        # All independent strategy sells are evaluated before any buys.
        if self.spy_lot > 0 and not self.spy_order_pending and spy_crossed_below:
            self.spy_order_pending = True
            self.MarketOrder(spy, -self.spy_lot, tag="Strategy A sell")

        if (
            self.aapl_lot > 0
            and not self.aapl_order_pending
            and float(self.aapl_rsi.Current.Value) > 60
        ):
            self.aapl_order_pending = True
            self.MarketOrder(aapl, -self.aapl_lot, tag="Strategy B sell")

        if self.spy_lot == 0 and not self.spy_order_pending and spy_crossed_above:
            quantity = self.CalculateOrderQuantity(spy, self.SPY_ALLOCATION)
            if quantity > 0:
                self.spy_order_pending = True
                self.MarketOrder(spy, quantity, tag="Strategy A buy")

        if (
            self.aapl_lot == 0
            and not self.aapl_order_pending
            and self.aapl_red_streak >= 3
            and float(self.Portfolio.Cash) >= self.AAPL_PURCHASE_DOLLARS
        ):
            quantity = floor(self.AAPL_PURCHASE_DOLLARS / float(aapl_bar.Close))
            if quantity > 0:
                self.aapl_order_pending = True
                self.MarketOrder(aapl, quantity, tag="Strategy B buy")

    def OnOrderEvent(self, order_event):
        symbol = order_event.Symbol
        if order_event.Status == OrderStatus.Filled or order_event.Status == OrderStatus.PartiallyFilled:
            fill_quantity = int(order_event.FillQuantity)
            if symbol == self.symbols["SPY"]:
                self.spy_lot = max(0, self.spy_lot + fill_quantity)
            elif symbol == self.symbols["AAPL"]:
                self.aapl_lot = max(0, self.aapl_lot + fill_quantity)

        if order_event.Status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]:
            if symbol == self.symbols["SPY"]:
                self.spy_order_pending = False
            elif symbol == self.symbols["AAPL"]:
                self.aapl_order_pending = False

