        spy_close = bars["SPY"].Close
        aapl_close = bars["AAPL"].Close

        spy_ready = self.spy_sma.IsReady and old_spy_sma is not None
        aapl_ready = self.aapl_rsi.IsReady

        if spy_ready:
            if self.strategy_a_shares > 0:
                crossed_below = (
                    old_spy_close >= old_spy_sma
                    and spy_close < self.spy_sma.Current.Value
